// Clientes inactivos que aún no han sido contactados (límite anti-bloqueo)
function aFecha(v) {
  if (!v) return null;
  v = String(v).trim();
  let m = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(v);
  return isNaN(d) ? null : d;
}
function normTel(t) {
  t = String(t || '').replace(/\D/g, '');
  if (t.length === 10 && t.startsWith('3')) t = '57' + t;
  return t;
}
const cfg = $('⚙️ Config').first().json;
const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const MS_DIA = 86400000;

const salida = [];
for (const item of $input.all()) {
  if (salida.length >= cfg.maximo_por_corrida) break;
  const fila = item.json;
  if (String(fila.Reactivado || '').trim().toUpperCase() === 'SI') continue;
  const tel = normTel(fila.Telefono);
  const ultima = aFecha(fila.UltimaCompra);
  if (!tel || !ultima) continue;
  const diasSinComprar = Math.round((hoy - ultima) / MS_DIA);
  if (diasSinComprar >= cfg.dias_inactividad) {
    salida.push({ json: { ...fila, telefono_normalizado: tel, dias_sin_comprar: diasSinComprar } });
  }
}
return salida;

const cliente = $('Loop Clientes').first().json;
const r = $json;
const mensaje = (r.message?.content || r.output || r.text || '').trim();
return [{ json: { telefono: cliente.telefono_normalizado, mensaje, row_number: cliente.row_number } }];
